1	import { test, describe } from 'node:test';
2	import assert from 'node:assert/strict';
3	
4	import { buildInvoice, totalRevenueForMonth } from '../src/projections/billing.ts';
5	import { billableMinutes, rawMinutesBetween } from '../src/lib/duration.ts';
6	import type { DomainEvent } from '../src/domain/events.ts';
7	
8	function completedBooking(opts: {
9	  id: string; user?: string; resourceId?: string;
10	  startAt: string; endAt: string; actualStartAt: string; actualEndAt: string;
11	}): DomainEvent[] {
12	  const user = opts.user ?? 'u-pat';
13	  return [
14	    {
15	      type: 'BookingRequested', bookingId: opts.id, occurredAt: opts.startAt, actorId: user,
16	      userId: user, userRole: 'STUDENT', resourceId: opts.resourceId ?? 'gpu-a100-01',
17	      startAt: opts.startAt, endAt: opts.endAt, requiresApproval: false,
18	    },
19	    { type: 'BookingStarted', bookingId: opts.id, occurredAt: opts.actualStartAt, actorId: user, actualStartAt: opts.actualStartAt },
20	    { type: 'BookingCompleted', bookingId: opts.id, occurredAt: opts.actualEndAt, actorId: user, actualEndAt: opts.actualEndAt },
21	  ] as DomainEvent[];
22	}
